// Renders prisma/schema.prisma from prisma/schema.base.prisma for the
// provider implied by DATABASE_URL. Run automatically by postinstall and the
// db:* tasks; edit schema.base.prisma, never the generated file.
import 'dotenv/config';
import { readFileSync, writeFileSync } from 'node:fs';
import { LONG_TEXT, providerFromUrl } from '../prisma/provider.mjs';

const provider = providerFromUrl(process.env.DATABASE_URL);
const base = readFileSync(new URL('../prisma/schema.base.prisma', import.meta.url), 'utf8');
const out =
    '// GENERATED by scripts/prisma-schema.mjs from schema.base.prisma. Do not edit.\n' +
    base
        .replaceAll('{{provider}}', provider)
        .replaceAll(' {{longtext}}', LONG_TEXT[provider] ? ` ${LONG_TEXT[provider]}` : '');
writeFileSync(new URL('../prisma/schema.prisma', import.meta.url), out);
console.log(`prisma/schema.prisma rendered for ${provider}`);
